function makeCourse(code: string, title: string, credits: number, category: string, prerequisites: string, instructor: string, description: string,
  chapters: ({ t: string; l: string[] } | { t: string; lessons: { title: string; content: string; duration: number }[] })[],
  questions: SeedQuestion[]
): SeedCourse {
  return {
    code, title, credits, category, prerequisites, instructor, description,
    chapters: chapters.map(ch => {
      if ('lessons' in ch) return { title: ch.t, lessons: ch.lessons }
      return {
        title: ch.t,
        lessons: ch.l.map(l => {
          const [t, c, d] = l.split('|')
          return { title: t, content: c, duration: parseInt(d) }
        })
      }
    }),
    quiz: { title: `${code} - ${title} Assessment`, passing_score: 70, questions },
  }
}

function q(question: string, options: string[], correct: number, explanation: string): SeedQuestion {
  return { question, options, correct, explanation }
}
